const projects=[
{title:'AMBEBE',type:'COMÉRCIO ELECTRÓNICO',category:'web',description:'Plataforma orientada para o mercado moçambicano, com gestão de produtos, vendas, pedidos, stock e administração.',tags:['Next.js','React','TypeScript','Express','Prisma','MySQL'],bg:'#e9effe',accent:'#2563eb',visual:'dashboard',label:'AMBEBE',links:[['Frontend','https://github.com/mbeve235/ambebe-frontend'],['Backend','https://github.com/mbeve235/ambebe-backend']]},
{title:'Sistema de Gestão Escolar',type:'APLICAÇÃO WEB',category:'web',description:'Gestão de alunos, docentes, turmas, disciplinas, planos de ensino e notas, com controlo de acesso e acompanhamento académico.',tags:['PHP','MySQL','JavaScript','Laravel'],bg:'#e9f5f0',accent:'#167c65',visual:'dashboard',label:'Gestão Escolar'},
{title:'Aplicações desktop em Java',type:'PROGRAMAÇÃO ORIENTADA A OBJECTOS',category:'desktop',description:'Aplicações integradas com bases de dados relacionais, organizadas em classes e com operações de gestão de informação.',tags:['Java','POO','Bases de dados'],bg:'#ecedf5',accent:'#475569',visual:'code'},
{title:'Chatbot para WhatsApp',type:'INTELIGÊNCIA ARTIFICIAL & AUTOMAÇÃO',category:'auto',description:'Automação de mensagens e integração de inteligência artificial para apoiar interacções com utilizadores.',tags:['Python','API da OpenAI','APIs'],bg:'#e3f3ea',accent:'#16a34a',visual:'chat'},
{title:'Sistema de Gestão de Notas',type:'DESENVOLVIMENTO WEB',category:'web',description:'Registo e acompanhamento de avaliações escolares, com organização de alunos, disciplinas, docentes e resultados académicos.',tags:['PHP','MySQL','HTML','CSS','JavaScript'],bg:'#efeafe',accent:'#7c3aed',visual:'dashboard',label:'Resultados académicos'},
{title:'Bíblia Online',type:'APLICAÇÃO WEB · PLANEADA',category:'web',description:'Projecto planeado para leitura bíblica, com diferentes traduções, selecção de livros e capítulos e administração de versões.',tags:['HTML','CSS','JavaScript','PHP','MySQL'],bg:'#f4efe5',accent:'#a16207',visual:'book',planned:true}
];
function visual(p){if(p.visual==='code')return '<div class="visual-code"><span class="comment">// Gestão de informação</span><br><span class="purple">public class</span> Aplicacao {<br>&nbsp; Database db;<br><br>&nbsp; <span class="purple">public void</span> guardar() {<br>&nbsp;&nbsp; db.connect();<br>&nbsp;&nbsp; <span class="green">// Criar. Consultar. Actualizar.</span><br>&nbsp; }<br>}</div>';if(p.visual==='chat')return '<div class="visual-chat"><div class="chat-head">● Assistente virtual</div><div class="bubble">Olá! Como posso ajudar?</div><div class="bubble reply">Gostaria de saber mais.</div><div class="bubble">Vamos encontrar a informação de que precisas. ✨</div></div>';if(p.visual==='book')return '<div class="book"><small>LEITURA · LIVROS · CAPÍTULOS</small><hr><b>Bíblia Online</b><p>Um espaço dedicado à leitura.<br>Diferentes traduções, num só lugar.</p><hr><p>Génesis &nbsp; · &nbsp; Capítulo 1</p></div>';return '<div class="mini-app"><div class="mini-sidebar">'+p.label+'<i></i><i></i><i></i><i></i></div><div class="mini-content"><div class="mini-title"><span>Visão geral</span><span>◉</span></div><div class="mini-stats"><i></i><i></i><i></i></div><div class="bars">'+[35,70,50,90,63,80,100,75].map(n=>'<i style="height:'+n+'%"></i>').join('')+'</div><div class="mini-lines"><i></i><i></i><i></i></div></div></div>'}
document.getElementById('project-grid').innerHTML=projects.map(p=>'<article class="project" data-category="'+p.category+'"><div class="project-visual" aria-hidden="true" style="--bg:'+p.bg+';--accent:'+p.accent+'">'+visual(p)+'</div><div class="project-body"><div class="project-type">'+p.type+'</div><h3>'+p.title+'</h3><p>'+p.description+'</p><div class="project-tags">'+p.tags.map(t=>'<span>'+t+'</span>').join('')+'</div><div class="project-bottom">'+(p.links?p.links.map(l=>'<a target="_blank" rel="noopener noreferrer" href="'+l[1]+'">'+l[0]+' ↗</a>').join(''):'<span>'+(p.planned?'Em planeamento':'Repositório ainda não disponibilizado')+'</span>')+'</div></div></article>').join('');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.project').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter})}));
document.getElementById('year').textContent=new Date().getFullYear();
